package com.fromagerie_back.controller;
import java.util.*; import org.springframework.web.bind.annotation.*; import com.fromagerie_back.dto.LotLaitDtos.*; import com.fromagerie_back.service.UtilisationLotLaitService; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/fabrications/{fabricationId}/lots-lait") public class FabricationLotLaitController{private final UtilisationLotLaitService service;public FabricationLotLaitController(UtilisationLotLaitService s){service=s;}@GetMapping public List<UtilisationResponse> get(@PathVariable Long fabricationId){return service.find(fabricationId);}@PutMapping public List<UtilisationResponse> put(@PathVariable Long fabricationId,@Valid @RequestBody List<UtilisationRequest> r){return service.replace(fabricationId,r);}}
